private List<Rate> ratesOf(String sheetId, LocalDate asOf) {
    return asOf == null ? withOlder(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId))
            : ratesAsOf(sheetId, asOf);
