 * falls back on the version it saw.
 */
public List<Rate> withOlder(List<Rate> sheetRates) {
    for (Rate rate : sheetRates) {
        if (rate.getForwardAfter() != null) {
            rate.setOlder(rateVersions.findByRateIdOrderByVersionAsc(rate.getId()));
        }
    }
