    List<Rate> stood = RateLog.stood(sheetId, grade, rollup.withOlder(rates.findBySheetIdAndGrade(sheetId, grade)),
            logs.findBySheetIdAndGradeOrderByIdAsc(sheetId, grade), asOf);
